var DATA = {"mode": "ratio", "r": 3, "before": 12, "fits": "over D-sub, grips 4 mm wire"};
function show(k,v){console.log(k+": "+v);}
var m=DATA.mode;
if(m==="ratio"){
  show("Ratio",DATA.r+":1");
  show("Supplied",DATA.before+" mm");
  show("Recovered",(Math.round(DATA.before/DATA.r*10)/10)+" mm");
  show("Fits over",DATA.fits);
}else if(m==="pick"){
  show("Bundle diameter",DATA.bundle+" mm");
  show("Pick",DATA.pick);
  show("Rule","supplied dia > connector, recovered dia < wire");
}else if(m==="print"){
  show("Printers","thermal-transfer label printers");
  show("Models","Brady BMP71, Dymo Rhino 5200 + heat-shrink cartridges");
  show("Ink","permanent, smudge-proof when shrunk");
}else if(m==="apply"){
  show("Tool",DATA.tool);
  show("Temperature",DATA.temp);
  show("Technique","even passes, rotate the bundle");
}else if(m==="adhesive"){
  show("Dual-wall","adhesive lining melts and seals");
  show("Use","outdoor, automotive, strain relief");
}else if(m==="cut"){
  show("Label length",DATA.len+" mm");
  show("Cut",DATA.len+" mm + 10% for shrink pullback");
  show("Total",(Math.round(DATA.len*1.1))+" mm");
}else if(m==="harness"){
  show("Wires in harness",DATA.n);
  show("Sleeve","one printed sleeve per wire + one harness band");
}else if(m==="color"){
  show("Colors",DATA.colors.join(", "));
  show("Code","by voltage or signal family");
}else if(m==="tape"){
  show("Heat shrink","permanent, labeled, sealed");
  show("Electrical tape","temporary, gummy, unlabeled");
}else if(m==="mistake"){
  show("Mistake",DATA.bad);show("Instead",DATA.good);
}else if(m==="store"){
  show("Storage","cool, dark, in the tube");
  show("Note","heat and UV pre-shrink the tubing");
}else if(m==="test"){
  show("Test","tug the cooled sleeve");
  show("Pass","no rotation, no slip");
}else if(m==="workflow"){
  console.log("Sleeving workflow:");DATA.steps.forEach(function(s,i){console.log("  "+(i+1)+". "+s);});
}
